{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Prucalopride, which shares the 4-amino-5-chloro-2-methoxybenzamide core and a piperidine amide motif, has absolute oral bioavailability greater than 90% in humans, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Metoclopramide, containing the identical substituted benzamide core with a basic amine side chain, shows mean oral bioavailability of 76% (range 64-97%) in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Amisulpride, a related substituted benzamide with a basic pyrrolidine side chain, has absolute bioavailability of approximately 50% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Lumateperone, a structurally more distant molecule with a fluorophenyl acyl piperidine, has very low absolute bioavailability of 4.4%, but its different scaffold and extensive first-pass metabolism limit transferability to the query; this is weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 4-amino-5-chloro-2-methoxybenzamide with a basic piperidine and a fluorophenoxypropyl substituent. The closest analogues prucalopride and metoclopramide have high oral bioavailability (>90% and ~76%), and related benzamide/piperidine drugs also exceed 20%. Low-bioavailability outliers are structurally dissimilar or contain polar sulfonyl/sulfamoyl groups absent in the query. Therefore predict high F.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the query molecule.",
    "First-pass metabolism and transporter-mediated efflux not experimentally assessed.",
    "Solubility and permeability not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

